import json, csv
from pathlib import Path
OUT=Path(__file__).parent
talks=[]; items=[]; problems=[]; corrections=[]
def talk(r,date,speaker,pages,title,summary,kind='talk'):
    talks.append(dict(record=r,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(r,pages,kind,title,notes,statement,reconstruction='',cls='E',fate='',present='',literal='correct with missing hypotheses',match='exact',verification='read the result',development='none',problem='',worth='',refs=None,confidence='high',area='Pseudodifferential operators'):
    n=1+sum(x['record']==r for x in items)
    if not present: present='As of November 2026: established under the stated hypotheses; no unresolved problem is asserted by this occurrence.'
    items.append(dict(id=f'1965-{r}.{n}',record=r,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=present,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=refs or [],confidence=confidence,area=area))
def correction(page,place,reading,correct,evidence,applies='both'):
    corrections.append(dict(page=page,place=place,transcription_reads=reading,should_read=correct,evidence=evidence,applies_to=applies))
def save():
    for suffix,data in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/f'late_{suffix}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'late_corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to']);w.writeheader();w.writerows(corrections)

talk(81,'1966-02-14','M. S. Agranovich','P000125-P000128','Pseudodifferential and singular integral operators',r'''The first Agranovich lecture introduces homogeneous symbols, spherical harmonic kernels, rough-symbol boundedness and the first rules of symbolic calculus. It is primarily an exposition of the already published 1965 theory, not a preview whose first publication was necessarily after the seminar. Several handwritten slips in the boundedness argument are separated from transcription mistakes. The lecture ends in the upper part of P000128, before Gelfand's integral-geometry heading.''')
A=['agranovich1965elliptic']
af=r'Already treated in \citet{agranovich1965elliptic}, especially \S\S6--8; this is expository by the date of the talk.'
item(81,'P000125','definition','Homogeneous symbol and Fourier quantization',r'The notes write \(Au=F^{-1}[\sigma(x,\xi)Fu]\), with \(\sigma\) positively homogeneous of degree \(s\geq0\).',r'For a smooth symbol away from \(\xi=0\), satisfying \(\sigma(x,t\xi)=t^s\sigma(x,\xi)\) for \(t>0\), left quantization is \(Au(x)=(2\pi)^{-n}\int e^{ix\cdot\xi}\sigma(x,\xi)\widehat u(\xi)\,d\xi\), initially on test functions, with an oscillatory interpretation when necessary.',r'The Fourier normalization and the meaning of the inverse transform with the external parameter \(x\) are supplied. A cutoff near zero gives the standard smooth symbol class.',fate=af,refs=A)
item(81,'P000125','construction','Differential operators, multiplication and the square-root Laplacian',r'Examples are \(\sum_{|\alpha|=m}a_\alpha D^\alpha\), \(s=0\), \(\sigma(x)\), and \(\Lambda=\sqrt{-\Delta}\).',r'With \(D_j=-i\partial_{x_j}\), a homogeneous differential operator has symbol \(\sum_{|\alpha|=m}a_\alpha(x)\xi^\alpha\). A symbol independent of \(\xi\) quantizes as multiplication. On \(\mathbb R^n\), \(\sqrt{-\Delta}\) is the Fourier multiplier \(|\xi|\) on its natural Sobolev domain.',r'These examples specify principal homogeneous symbols; a general differential operator also has lower-degree terms.',fate=af,refs=A,literal='correct')
item(81,'P000125','method','Low-frequency regularization of negative orders',r'For \(s<0\), multiply by \(\varphi(|\xi|)\), zero near zero and one away from zero; the difference is called inessential.',r'Two smooth cutoffs agreeing for large \(|\xi|\) give symbols differing in a compact frequency annulus. Their properly localized operators differ by an operator with a smooth kernel and hence by an operator of order \(-\infty\).',r'One cannot subtract an undefined unregularized singular multiplier at zero. The assertion compares two admissible regularizations and is local in the base variable.',fate=af,refs=A)
item(81,'P000125-P000126','construction','Spherical harmonic expansion and homogeneous kernels',r'\(\sigma(x,\xi)=\sum_{m,k}a_{mk}(x)Y_{mk}(\xi/|\xi|)\). For \(m>0\), the inverse multiplier kernel is a constant times \(Y_{mk}(z/|z|)|z|^{-n}\).',r'Choose orthonormal spherical harmonics of degree \(m\). In the distributional principal-value sense, the Fourier transform preserves each nonconstant harmonic type and maps \(|z|^{-n}Y_{mk}(z/|z|)\) to \(\gamma_mY_{mk}(\xi/|\xi|)\), with \(|\gamma_m|\asymp m^{-n/2}\) for the conventional transform normalization.',r'The exact complex phase and numerical constant depend on the Fourier convention; only the reciprocal relation and asymptotic order are used below. The degree-zero term is excluded from this principal-value kernel.',fate=r'\citet{agranovich1965elliptic}, \S6, supplies this harmonic-kernel correspondence.',refs=A)
item(81,'P000125-P000126','definition','Cancellation and the missing multiplication term',r'The notes collect the harmonic kernels into a homogeneous \(K\), state a sphere mean-zero condition, and display a principal-value integral for \(A\).',r'An order-zero operator of this form is \(Au=a_{00}(x)u+\operatorname{pv}\int K(x,x-y)u(y)\,dy\), where \(K(x,tz)=t^{-n}K(x,z)\) and \(\int_{S^{n-1}}K(x,\omega)\,d\omega=0\).',r'The multiplication term must be restored unless the degree-zero spherical coefficient vanishes. The fixed first argument of the cancellation condition is the base point \(x\), not the integration variable.',fate=af,refs=A,literal='false as written',development='annotated')
item(81,'P000126','construction','Fourier-side kernel and stabilization at infinity',r'The notes set \(\sigma=\sigma_\infty+\sigma^{\prime}\), call \(\sigma^{\prime}\) finite in \(\xi\), and give a Fourier-side integral with \(\widehat{\sigma^{\prime}}(\xi-\eta,\eta)\).',r'For a symbol equal to \(\sigma_\infty(\xi)\) outside a compact set in \(x\), \(\widehat{Au}(\xi)=\sigma_\infty(\xi)\widehat u(\xi)+(2\pi)^{-n}\int\widehat{\sigma^{\prime}}_x(\xi-\eta,\eta)\widehat u(\eta)\,d\eta\), with the corresponding normalization adjustment for a unitary transform.',r'Compact support must refer to \(x\) in this argument. A nonzero homogeneous function cannot be compactly supported in \(\xi\). The scan itself says \(\xi\); this is a notebook slip, not a transcription error.',fate=r'This representation is part of the 1965 calculus; compare \citet{agranovich1965elliptic} and the independently published \citet{kohn1965algebra}.',refs=A+['kohn1965algebra'],literal='false as written',development='annotated')
item(81,'P000126','remark','Smooth equivalence and rough-symbol inequivalence',r'The two definitions are said to agree for smooth symbols but to lead to different classes after smoothness is relaxed.',r'Left/right quantizations have the same principal symbol in a smooth classical calculus. For rough symbols, boundedness and the ability to convert quantizations require explicit regularity; no equivalence follows merely from the formal integral expressions.',r'The notes do not specify a pair of rough symbol spaces for a sharp inequivalence theorem. This occurrence records the methodological warning, not an unrecorded counterexample.',fate=af,refs=A,match='partial',confidence='medium')
item(81,'P000126','definition','Sobolev scale and order convention',r'\(\|u\|_\ell^2=\int(1+|\xi|^2)^\ell|\widehat u|^2\); an order-\(s\) operator maps \(H^\ell\) to \(H^{\ell-s}\).',r'For symbols in the smooth uniform class \(S^s_{1,0}\), or for properly supported local operators, \(A:H^\ell_{\mathrm{comp}}\to H^{\ell-s}_{\mathrm{loc}}\) continuously. Uniform global symbol estimates give the global bounded map on \(\mathbb R^n\).',r'Uniform coefficient bounds or localization are needed on a noncompact base.',fate=af,refs=A)
item(81,'P000126-P000127','theorem','Angular Sobolev regularity sufficient for L2 boundedness',r'The displayed criterion assumes \(q>(n-1)/2\) and \(\sup_x\|\sigma(x,\cdot)\|_{H^q(S^{n-1})}<\infty\).',r'For \(n\geq2\), a degree-zero symbol measurable in \(x\) with \(M=\operatorname*{ess\,sup}_x\sum_{m,k}(1+m)^{2q}|a_{mk}(x)|^2<\infty\), \(q>(n-1)/2\), defines an \(L^2\)-bounded left-quantized operator. Its norm is at most a dimensional constant times \(M^{1/2}\).',r'The weight \(1+m\) retains the constant harmonic; the printed use of \(m\) alone is harmless only after separating multiplication.',fate=r'\citet{agranovich1965elliptic}, Proposition 7.1 and Remark 7.1, already give the criterion and its rough-base-variable interpretation.',refs=A)
item(81,'P000126-P000127','method','Addition theorem and the boundedness proof',r'The proof uses Schwarz, the sum \(\sum_k|Y_{mk}|^2\), and a series with exponent \(n-2\). Several factors and signs in the handwritten estimates are lost or reversed.',r'Pointwise Schwarz gives \(|Au(x)|^2\leq M\sum_{m,k}(1+m)^{-2q}|Y_{mk}(D)u(x)|^2\). Plancherel and the addition theorem give \(\|Au\|_2^2\leq C M\|u\|_2^2\sum_m(1+m)^{n-2-2q}\). The last series converges exactly when \(2q>n-1\).',r'The two Schwarz sums are multiplied, not equated; \(|\widehat u|^2\) remains under the Fourier integral, and the weight in the second sum has exponent \(-2q\). These are mathematical repairs to handwriting verified in the scans.',fate=r'The complete estimate is in \citet{agranovich1965elliptic}, proof of Proposition 7.1.',refs=A,literal='false as written',development='annotated')
item(81,'P000127','remark','Endpoint and absence of base-variable smoothness',r'The notes say \ru{По $\xi$ гладк. не нужно} near the angular argument and discuss divergence at the limiting exponent.',r'The angular criterion needs no regularity in \(x\). At \(q=(n-1)/2\), its proof gives a harmonic series and no uniform bound; individual operators, such as the identity, remain bounded. The endpoint is not a claim that every symbol there is unbounded.',r'In this local context the handwritten \(\xi\) must be \(x\); otherwise it contradicts the angular hypothesis. A later, different criterion genuinely removes angular regularity.',fate=r'\citet{agranovich1965elliptic}, Remark 7.1, discusses the sharp failure of the general convergence assertion.',refs=A,literal='false as written',development='annotated')
item(81,'P000127','theorem','Kernel version of the angular criterion',r'For \(K(x,z)=k(x,z/|z|)|z|^{-n}\), the threshold becomes \(q>-1/2\).',r'If \(k(x,\cdot)\) has zero spherical mean, is measurable in \(x\), and is uniformly in \(H^q(S^{n-1})\), \(q>-1/2\), then the associated distributional singular integral is \(L^2\)-bounded. For negative \(q\), the angular kernel is interpreted as a distribution.',r'The harmonic transform raises the angular Sobolev index by \(n/2\). Cancellation and the distributional interpretation are essential.',fate=r'\citet{agranovich1965elliptic}, \S\S6--7, contains the symbol-to-kernel transfer.',refs=A)
item(81,'P000127','construction','Planar Riesz-transform example',r'The example is \(z_1/(z_1^2+z_2^2)^{3/2}\).',r'In \(\mathbb R^2\), \(\operatorname{pv}z_1/|z|^3\) is, up to the Fourier normalization and sign, the kernel of the first Riesz transform, whose multiplier is a constant times \(i\xi_1/|\xi|\); it is \(L^2\)-bounded.',fate=af,refs=A,literal='correct')
item(81,'P000127','theorem','A complementary criterion using base-variable derivatives',r'Compactly supported dependence on \(x\) with \(n+1\) derivatives gives Fourier decay \((1+|\xi-\eta|^2)^{-(n+1)/2}\).',r'If \(\sigma^{\prime}(\cdot,\eta)\) is supported in one fixed compact set and its \(x\)-derivatives through order \(n+1\) are uniformly bounded, then \(|\widehat{\sigma^{\prime}}_x(\zeta,\eta)|\leq C(1+|\zeta|)^{-n-1}\). The Fourier kernel is dominated by an \(L^1\) convolution kernel, hence defines a bounded \(L^2\) operator, without angular smoothness.',r'Uniformity in \(\eta\) and fixed spatial support are supplied; boundedness of the separate multiplier \(\sigma_\infty\) is also needed.',fate=af,refs=A)
item(81,'P000127','theorem','First symbolic composition rule',r'The notes announce that \(AB-\sigma_1\sigma_2(x,D)\) is subordinate.',r'For smooth classical operators of orders \(s_1,s_2\), \(AB-\operatorname{Op}(\sigma_{s_1}(A)\sigma_{s_2}(B))\) has order at most \(s_1+s_2-1\), provided the representative operators have only the stated principal homogeneous term plus lower-order remainders.',r'Proper support is understood locally. Rough-symbol boundedness alone does not imply this calculus.',fate=r'The result precedes the seminar in \citet{agranovich1965elliptic} and \citet{kohn1965algebra}; record 84 continues its proof.',refs=A+['kohn1965algebra'])
item(81,'P000127','theorem','Pseudolocality and localization',r'Pseudolocality and extension to manifolds are announced.',r'For a smooth pseudodifferential operator, \(\operatorname{sing\,supp}(Au)\subseteq\operatorname{sing\,supp}(u)\). If smooth compact cutoffs have disjoint supports, \(\varphi A\psi\) has a smooth kernel.',r'The full smoothing assertion uses the smooth calculus, stronger than the one-order estimates elsewhere in the notes.',fate=af,refs=A)
item(81,'P000128','theorem','Left and right quantizations differ below principal order',r'The Fourier kernel uses either \(\sigma(\xi-\eta,\eta)\) or \(\sigma(\xi-\eta,\xi)\); Taylor expansion makes their difference subordinate.',r'For a smooth symbol of order \(s\), left and right quantizations using the same symbol agree modulo order \(s-1\). The full conversion is an asymptotic series involving mixed base and frequency derivatives.',r'Only the first-order consequence, not a complete asymptotic formula, is asserted by the notes.',fate=af,refs=A)
item(81,'P000128','theorem','Adjoint principal symbol',r'The adjoint reverses the two quantizations and conjugates the symbol.',r'With a fixed smooth positive density and Hermitian metrics, the formal adjoint of an order-\(s\) operator has principal symbol \(\sigma_s(A)^*\), the fiberwise Hermitian transpose. The remainder is of order \(s-1\).',r'For scalar operators the star is complex conjugation. Density and bundle metrics matter only below the leading symbol in a compatible local trivialization.',fate=af,refs=A)
item(81,'P000128','question','Gelfand asks about replacing polynomials in the algebra',r'Gelfand asks \ru{Можно ли зам. многочл. на другие, чтобы получ. та же алгебра.}',r'No precise question can be recovered: the polynomials to be replaced, the admissible replacement functions and the sense of equality of algebras are not specified.',r'Possible readings include generating symbols, harmonic expansions, or an alternative quantization. None is imposed as the historical statement.',cls='F',fate=r'The nearby 1965 calculus papers clarify context but do not identify this wording with a definite published problem.',present='As of November 2026: unidentifiable from the surviving sentence; no claim of an open mathematical problem is warranted.',literal='not determinable',match='none found',verification='unresolved lead',confidence='low')
item(81,'P000128','remark','Cotangent location of the principal symbol',r'The lecture ends by placing the symbol on the cotangent bundle.',r'The scalar principal symbol of an order-\(s\) operator is a degree-\(s\) homogeneous function on \(T^*M\setminus0\); for operators between bundles it is a section of \(\operatorname{Hom}(\pi^*E,\pi^*F)\).',r'The bundle-valued statement is the modern completion of the scalar shorthand; record 84 supplies the coordinate argument.',fate=af,refs=A,literal='correct')
save()

talk(86,'1966-03-21','V. A. Borovikov; comment by I. M. Gelfand','P000138','Boundary integrals and area',r'''After the dated March heading, Borovikov states a double boundary cosine integral for area. Gelfand follows with a very compressed slice-area/volume formula. The former is valid with convexity and consistent inward chord-angle conventions; it has no missing distance denominator. The latter is false for a single slicing direction and remains uncertain as a historical assertion because an angular average may have been omitted.''')
item(86,'P000138','theorem','Double boundary cosine integral for planar area',r'With the normals drawn at \(M,N\), \(\iint\cos\varphi_M\cos\varphi_N\,dM\,dN=2\pi S\), where \(S\) is area.',r'Let \(K\subset\mathbb R^2\) be a bounded strictly convex domain with \(C^2\) boundary. At each ordered pair of distinct boundary points, take the inward normal and the chord directed toward the other endpoint; let \(c_M,c_N\) be their nonnegative cosines. Then \(\int_{\partial K}\int_{\partial K}c_Mc_N\,ds_Mds_N=2\pi|K|\).',r'Convexity, arc-length measures and the two endpoint angle conventions are supplied. Chord-space coordinates give \(|dp\,d\theta|=c_Mc_N|M-N|^{-1}ds_Mds_N\); the pair integral is twice the integral of chord length over unoriented lines. A complete independent derivation is included in the audit notes.',fate=r'This is a direct consequence of classical line-space integration: \citet{santalo1953introduction} predates the talk; the relevant measure is checked in \citet{santalo1989integral}, \S1.2. No exact Borovikov publication or priority claim was verified.',present='As of November 2026: the stated convex-domain identity is verified by the included derivation; attribution of this exact presentation remains unresolved.',match='partial',verification='read the result',refs=['santalo1953introduction','santalo1989integral'],confidence='medium',area='Integral geometry',development='annotated')
item(86,'P000138','claim','Gelfand slice-area formula and the missing directional average',r'The scan shows \(M(\int S^{\prime\,2}(x)\,dx)=V\) and explicitly calls \(M\) a universal constant. The prime reading is marked uncertain in the transcription.',r'If \(S(t)\) is the area of planar sections of a three-dimensional body in one fixed direction, no universal scalar \(M\) makes \(M\int|S^{\prime}(t)|^2dt=V\) for all bodies. For an ellipsoid with semiaxes \(a,b,c\), sliced perpendicular to the \(c\)-axis, the ratio of the integral to volume is \(2\pi ab/c^2\).',r'An angularly integrated Radon-Plancherel identity does have a universal constant: with ordinary area on \(S^2\), \(\int_{S^2}\int_{\mathbb R}|\partial_tR f(\omega,t)|^2dt\,d\omega=8\pi^2\|f\|_2^2\). Taking \(f=1_K\) gives volume. The notes do not record this angular integral, so it is a possible repair, not the recovered historical statement.',cls='F',fate=r'The nearby Gelfand integral-geometry literature supplies thematic context, but no exact match to this one-line formula with its stated constant was verified.',present='As of November 2026: the fixed-direction literal interpretation is disproved by the ellipsoid computation; the intended averaged statement remains textually uncertain.',literal='false as written',match='thematic only',verification='unresolved lead',refs=[],confidence='low',area='Integral geometry',development='annotated')
save()

talk(87,'1966-03-21','V. B. Lidskii','P000138','Zeta function of all zeros of an exponential-type entire function',r'''This compact announcement has an unusually exact later match: Lidskii and Sadovnichii's 1967 paper, especially Lemmas 2--3. The entire continuation concerns a branch-dependent sum over all nonzero zeros, with complete sectorial asymptotics. The comparison with the ordinary zeta function refers to the difference between all signed sine zeros and only the positive half.''')
L=['lidskii1967zeros'];lf=r'Published soon after in \citet{lidskii1967zeros}; the class definition and Lemmas 2--3 were read in full text.'
item(87,'P000138','definition','The exponential-asymptotic class of entire functions',r'\(f(z)=\sum_{k=1}^Ne^{\alpha_kz}\mathcal P_k(z)\), where \(\mathcal P_k\) are polynomial-plus-inverse-power asymptotic series.',r'The matching class consists of entire functions represented sectorially by finitely many exponential factors with analytic coefficients admitting complete differentiable asymptotic expansions \(P_k(z)\sim z^{\mu_k}\sum_{j\geq0}p_{kj}z^{-j}\), \(\mu_k\in\mathbb Z\), \(p_{k0}\neq0\), on a finite covering by open sectors outside a disk.',r'Complete asymptotics, sectorial analyticity and termwise differentiability are supplied from the published class \(K\). A formal divergent Laurent series by itself does not define an entire function.',cls='A',fate=lf,refs=L,area='Entire functions and spectral zeta functions')
item(87,'P000138','construction','All-zero zeta sum and its logarithm branch',r'\(\zeta(\sigma)=\sum z_n^{-\sigma}\), with \(z_n\) the zeros of \(f\).',r'Remove a possible power of \(z\) so that \(f(0)\neq0\), count all zeros with multiplicity, and choose a logarithm branch cut along a ray in a noncritical zero-free sector, avoiding the finite remaining zeros. Then \(Z(s)=\sum_n\exp(-s\operatorname{Log}z_n)\) initially converges for \(\operatorname{Re}s>1\).',r'The branch and exclusion of zero are indispensable. Changing the admissible cut can change the zeta function even though the root set is unchanged.',cls='A',fate=r'\citet{lidskii1967zeros}, \S1, definition (9)--(10) and Lemma 2.',refs=L,area='Entire functions and spectral zeta functions')
item(87,'P000138','theorem','Entire continuation by a Cauchy contour',r'The zeta function is said to be always entire, with proof by a Cauchy integral.',r'For the stated complete-asymptotic class and an admissible branch, the all-zero zeta function extends to an entire function of \(s\). A keyhole integral of \(z^{-s}f^{\prime}(z)/f(z)\) first represents it in a right half-plane; subtraction of arbitrarily many asymptotic terms continues it globally.',r'The unrestricted word always is valid only within the restored class. With a finite-order asymptotic expansion the paper guarantees only a corresponding half-plane continuation.',cls='A',fate=r'Exact result: \citet{lidskii1967zeros}, Lemma 3 and its footnote, Russian p. 55.',refs=L,area='Entire functions and spectral zeta functions')
item(87,'P000138','remark','Why this does not contradict the Riemann zeta pole',r'The notes say ordinary zeta does not use all the zeros of sine, with a reference to not starting at minus infinity.',r'For \(f(z)=\sin(\pi z)/z\), the nonzero zeros are \(\pm1,\pm2,\ldots\). With a branch assigning argument \(\pi\) to negative reals, the all-zero sum is \((1+e^{-i\pi s})\zeta_{\mathrm R}(s)\); the factor vanishes at \(s=1\), cancelling the sole pole. A sum only over positive zeros retains the pole.',r'The explicit example and branch choice reconstruct the compressed sine remark; they are checked algebraically rather than quoted as a formula from the seminar.',cls='A',fate=lf,refs=L,area='Entire functions and spectral zeta functions',development='annotated')
save()

talk(89,'1966-03-21','S. G. Gindikin','P000138-P000139','Generalized parabolic equations and cone-valued ellipticity',r'''Gindikin's announcement precedes Minlos in the physical notebook, although the catalogue numbers it 89. The 1967 multidimensional-time paper identifies both the hyperbolic replacement of the time derivative and the \(V\)-elliptic mapping. A reinspection corrects the transcription's pseudo-operator to hyperbolic operator. The random-walk/heat sentence before the boxed Minlos heading is recorded here with attribution uncertainty.''')
Q=['gindikin1967multitime'];qa='Partial differential equations and cone semigroups'
item(89,'P000138','construction','Hyperbolic time operator generalizing the heat equation',r'The supplied transcription says any pseudo-operator in place of \(\partial_t\); the scan reads \ru{любой гиперб. оператор} \(P(\partial/\partial t)\).',r'For a homogeneous polynomial \(p\) hyperbolic with respect to a direction in a proper cone \(V\subset\mathbb R^r\), a compatible \(V\)-elliptic spatial symbol produces a pluriparabolic operator with \(r\) time variables. In a consistent Fourier convention it has symbol \(q(\tau,\xi)=p(\tau+F(\xi))\). For one time variable and \(p(\tau)=\tau\), this recovers the ordinary parabolic construction.',r'Hyperbolicity is recovered from the scan; homogeneity, the cone and spatial positivity are restored from the precise published theorem. No claim is made for an arbitrary pseudodifferential time operator.',cls='A',fate=r'\citet{gindikin1967multitime}, \S3, Theorem 4, submitted 27 April 1966; the matching construction was read in the original four-page paper.',refs=Q,area=qa,development='annotated')
item(89,'P000139','definition','V-elliptic mappings and the hyperbolicity cone',r'The first line replaces ellipticity by \(V\)-ellipticity and refers to a cone corresponding to a hyperbolic polynomial.',r'In the Fourier-symbol convention where \(p(\tau+i\eta)\neq0\) for \(\eta\in V\), let \(F:\mathbb R^n\to\mathbb C^r\) have homogeneous polynomial components of common even degree. The required cone positivity is \(\operatorname{Im}F(\xi)\in V\) for real \(\xi\neq0\). Compactness of the unit sphere gives uniform interior positivity after normalization.',r'Factors of \(i\) move positivity between real and imaginary parts when differential-operator conventions change. The condition is stated at the symbol level to avoid silently mixing the notebook convention with the article convention.',cls='A',fate=r'Exact terminology and construction in \citet{gindikin1967multitime}, \S3, immediately before Theorem 4.',refs=Q,area=qa)
item(89,'P000138-P000139','construction','The associated family of operators is a cone semigroup',r'A family of operators is associated with \(P\), reducing to the parabolic family when \(P=\partial_t\).',r'Under the cone-positivity assumptions, commuting spatial Fourier multipliers generate a family \(T(t)\), \(t\) in the dual time cone, satisfying \(T(t)T(s)=T(t+s)\). Along a fixed interior ray the family is an ordinary parabolic evolution. The multidimensional-time fundamental solution combines this family with that of the hyperbolic time operator.',r'The source does not state all generator-domain conditions. This is the constant-coefficient Fourier-multiplier realization, not a theorem for arbitrary unbounded commuting operators.',cls='A',fate=r'\citet{gindikin1967multitime}, Theorem 5 and \S4, develop the family; \citet{gindikin1967cauchy} treats the related strongly homogeneous setting.',match='partial',refs=Q+['gindikin1967cauchy'],area=qa)
item(89,'P000139','remark','A random walk on a line and the heat equation',r'Before the boxed Minlos name, the source says \ru{Блуждание по прямой --- ур-е теплопроводности}.',r'A centered nearest-neighbor walk with step length \(\varepsilon\) and step time \(\varepsilon^2\), under diffusive scaling, converges to Brownian motion with variance rate one; its limiting density solves \(\partial_tu=\tfrac12\partial_x^2u\). Different variance/time normalizations change the diffusion constant.',r'This is the minimal standard mathematical interpretation; the walk law and scaling are absent. Page position favors continuity with Gindikin, but the isolated sentence may be an interjection.',fate=r'The diffusion-limit connection predates the seminar; \citet{donsker1951invariance} is a rigorous functional-limit reference, checked at bibliographic level.',match='partial',verification='publisher metadata checked',refs=['donsker1951invariance'],confidence='medium',area='Probability and diffusion')
save()

talk(88,'1966-03-21','R. A. Minlos','P000139','Ising lattice gas and thermodynamic limit',r'''The boxed Minlos heading introduces a lattice-gas configuration sum and the limit of its logarithm per volume. This is a brief substantive reminder, not a content-free heading, but no low-temperature contour theorem or phase-transition statement is actually recorded. It recurs to the elementary material indexed as 1964-3.1 and 1964-3.2.''')
item(88,'P000139','definition','Lattice configurations, occupied-neighbor energy and partition sum',r'\(L\) is a subset of the lattice, \(E(L)\) counts neighbors, \(N(L)\) counts points, and \(\Xi=\sum_Le^{-\beta E(L)-\mu N(L)}\).',r'For finite \(\Lambda\subset\mathbb Z^d\), a configuration is \(L\subseteq\Lambda\). With \(n_x=1_{x\in L}\), define \(N(L)=\sum_xn_x\) and, with a stated convention, \(E(L)=\sum_{\langle x,y\rangle}n_xn_y\) over unordered nearest-neighbor bonds. Then \(Z_\Lambda(\beta,\mu)=\sum_{L\subseteq\Lambda}e^{-\beta E(L)-\mu N(L)}\).',r'The finite region and bond-counting convention are supplied. The displayed sign penalizes occupied-neighbor pairs for positive \(\beta\); calling it ferromagnetic would require changing the interaction sign. The uncertain parenthesis is not expanded.',fate=r'An established lattice-gas formulation, recurring from 1964-3.1. \citet{ising1925ferromagnetismus} is the original model reference, checked bibliographically; no exact claim of equivalence to its notation is made.',match='partial',verification='publisher metadata checked',refs=['ising1925ferromagnetismus'],area='Statistical mechanics')
item(88,'P000139','theorem','Thermodynamic pressure and the normalization ambiguity',r'\(\lim(\ln Z)/N=f(\theta,\beta)\) is written; the first argument and the role of \(N\) are unclear.',r'For a fixed finite-range translation-invariant interaction on a finite-state lattice, along a van Hove sequence \(\Lambda_j\), \(\lim_j|\Lambda_j|^{-1}\log Z_{\Lambda_j}(\beta,\mu)\) exists and is independent of standard boundary conditions. A canonical free energy instead fixes particle density and uses a different partition sum.',r'In the grand-canonical sum above, \(N(L)\) varies across summands and cannot be the external volume denominator. The limit is reconstructed as pressure per site. No analyticity, coexistence or critical-temperature conclusion follows from this one line.',fate=r'This recurs from 1964-3.2. Pre-seminar thermodynamic-limit results are documented by \citet{fisher1964freeenergy}; its publisher abstract and metadata, rather than its full proof, were checked.',match='partial',verification='publisher metadata checked',refs=['fisher1964freeenergy'],area='Statistical mechanics')
save()

talk(85,'1966-02-28','A. A. Kirillov','P000137-P000138','Borel and Tits: algebraic and reductive groups',r'''This is an introductory report on Borel and Tits, not an announcement of a new classification. It passes from schemes and Chevalley's structure theorem to radicals, tori and root systems. Connectedness and the ground field are repeatedly tacit. The example calling an algebraic torus an abelian variety is incompatible with the standard algebraic-group meaning of torus and is retained as a source-level error.''')
B=['borel1965reductifs'];M=['milne2017groups'];ba='Algebraic groups'
bf=r'This is background for the explicitly cited \citet{borel1965reductifs}, published in 1965; no later priority claim is made.'
item(85,'P000137','definition','Schemes and Spec as the algebraic-geometric language',r'An algebraic variety is called a locally affine scheme; \(\operatorname{Spec}A\) is built from the prime ideals of \(A\).',r'An affine scheme is the locally ringed space \((\operatorname{Spec}A,\mathcal O_A)\), with \(\mathcal O_A(D(f))=A_f\). Schemes are locally affine. To describe an algebraic variety over a field one additionally specifies finite type, separatedness and the chosen reducedness/irreducibility convention.',r'The source conflates a scheme with a variety. These extra conditions are a modern terminology clarification, not a new theorem.',fate=bf,refs=B,match='partial',area=ba)
item(85,'P000137','claim','Prime ideals of the affine plane: the omitted generic point',r'For \(A=\mathbb C[x_1,x_2]\), primes are said to be point ideals or principal ideals generated by irreducible polynomials.',r'The primes are \((0)\), the height-one ideals \((P)\) for irreducible \(P\), and maximal point ideals \((x_1-a,x_2-b)\). The zero ideal is the generic point of the irreducible affine plane.',r'The missing zero ideal makes the literal exhaustive list false; the repair follows from unique factorization, dimension two and the algebraically closed base field.',fate=bf,literal='false as written',refs=B,match='partial',area=ba,development='annotated')
item(85,'P000137','definition','Algebraic groups and linear algebraic groups',r'The notes require a regular everywhere-defined multiplication and describe linear groups by algebraic equations inside \(GL(n,K)\).',r'An algebraic group is a finite-type group scheme over the base field, with multiplication, identity and inversion morphisms satisfying the group axioms. In the smooth-variety convention these maps are regular. An affine algebraic group admits a faithful finite-dimensional representation and thus a closed embedding into some \(GL_n\).',r'The inverse and identity morphisms and the finite-type requirement complete the abbreviated definition.',fate=bf,refs=B,area=ba)
item(85,'P000137','theorem','Chevalley structure theorem',r'A maximal linear subgroup \(G_0\) is asserted with abelian-variety quotient \(G/G_0\).',r'For a smooth connected algebraic group over a perfect field, there is a unique smooth connected affine normal subgroup \(G_{\mathrm{aff}}\) such that \(G/G_{\mathrm{aff}}\) is an abelian variety.',r'Connectedness, normality, smoothness and the field hypothesis are made explicit. Stronger scheme formulations over imperfect fields require a different smoothness statement.',fate=r'Known before the talk; the dated Barsotti--Chevalley theorem and a proof are checked in \citet{milne2017groups}, Theorem 8.27 and Notes 8.30--8.33.',refs=M,area=ba)
item(85,'P000137','theorem','Complete connected group varieties are abelian varieties',r'An abelian variety is a complete group, and is then commutative.',r'A smooth connected complete group variety over a field is commutative and projective; this is the abelian-variety notion used here. A nonconnected finite group scheme does not become commutative merely because it is complete.',r'Connectedness is necessary for the stated implication, and completeness is the algebraic properness condition rather than compactness of rational points.',fate=r'The pre-seminar result is checked in \citet{milne2017groups}, 8.20 and Theorem 8.45, with historical attribution.',refs=M,area=ba)
item(85,'P000137','theorem','Homomorphisms between affine groups and abelian varieties',r'Every homomorphism from an abelian variety to a linear group and conversely is declared trivial.',r'A homomorphism from an abelian variety to an affine algebraic group is trivial. A homomorphism from a smooth connected affine algebraic group to an abelian variety is also trivial. Without connectedness, a finite constant group can map nontrivially into torsion points.',r'The first direction follows from constancy of regular functions on a proper connected variety. In the reverse direction the connected affine image is simultaneously complete, hence trivial.',fate=r'This uses the classical affine-quotient and completeness results; modern precise forms are checked in \citet{milne2017groups}, Proposition 8.1 and \S8e.',refs=M,area=ba)
item(85,'P000137','claim','An algebraic torus is not an abelian variety',r'The scan explicitly says \ru{Например, алгебраический тор --- аб. мн-зие}.',r'A positive-dimensional algebraic torus, geometrically \((\mathbb G_m)^r\), is affine and not complete, so is not an abelian variety. A compact complex analytic torus is a different object; it is an abelian variety only with the appropriate projectivity condition.',r'No evidence establishes that an adjective or a negation was omitted by the transcriber. The literal algebraic statement is false; a possible analytic intention remains conjectural.',fate=r'The distinction is already present in the algebraic-group framework of \citet{borel1965reductifs}.',literal='false as written',refs=B,area=ba,development='annotated')
item(85,'P000137','construction','The additive and multiplicative groups',r'\(G_a,G_m\) are the additive and multiplicative groups of the field; a unipotent two-by-two matrix is drawn.',r'\(\mathbb G_a(R)=(R,+)\) is represented by \(x\mapsto\begin{pmatrix}1&x\\0&1\end{pmatrix}\); \(\mathbb G_m(R)=R^\times\) is represented by invertible one-by-one matrices. These are affine algebraic groups.',r'The functorial formulation supplies the scheme meaning without changing the elementary examples.',fate=bf,literal='correct',refs=B,area=ba)
item(85,'P000137','theorem','Solvable groups and one-dimensional factors',r'Solvability is described by a normal chain with factors \(G_a\) or \(G_m\), with a parenthetical warning that the definition is imprecise.',r'For a smooth connected solvable affine algebraic group over an algebraically closed field, a subnormal series can be chosen with successive quotients isomorphic to \(\mathbb G_a\) or \(\mathbb G_m\). The abstract derived-series definition of solvability is the invariant starting point.',r'The field and connectedness assumptions explain the notebook warning. Subnormal means normal in the preceding member; all members need not be normal in the whole group.',fate=bf,refs=B,area=ba)
item(85,'P000137-P000138','definition','Radical and unipotent radical',r'The radical is the maximal connected solvable normal subgroup; the unipotent radical is described using nilpotent matrices and \((u-E)^k=0\).',r'For a smooth connected affine algebraic group over an algebraically closed field, \(R(G)\) is its largest connected solvable normal subgroup and \(R_u(G)\) its largest connected unipotent normal subgroup. In a faithful representation, unipotent elements satisfy \((u-I)^N=0\); the matrix \(u\) itself is invertible, not nilpotent.',r'The nilpotent adjective applies to \(u-I\), as the formula on P000138 confirms.',fate=bf,refs=B,area=ba)
item(85,'P000138','definition','Reductive and semisimple groups',r'Reductive means the radical is a torus; semisimple means \(R(G)=1\).',r'For smooth connected affine groups over an algebraically closed field, reductive means \(R_u(G)=1\), equivalently that \(R(G)\) is a torus; semisimple means \(R(G)=1\). Over a general field these conditions are geometric, after base extension to an algebraic closure.',r'The word torus means an algebraic torus, not an abelian variety. General-field forms need not be split.',fate=bf,refs=B,area=ba)
item(85,'P000138','construction','GLn and SLn as the basic examples',r'\(GL(n,K)\) is reductive and \(SGL(n,K)\) is semisimple.',r'\(GL_n\) is reductive, with connected solvable radical its scalar torus; \(SL_n\) is semisimple for \(n\geq2\).',r'The written \(SGL\) is interpreted as \(SL\); no separate standard group \(SGL\) is defined.',fate=bf,refs=B,area=ba,development='annotated')
item(85,'P000138','theorem','Root-system classification and its scope',r'Four infinite series and five exceptional cases are listed, with maximal tori and root systems as the basic notions.',r'The irreducible reduced crystallographic root systems are \(A_n,B_n,C_n,D_n,E_6,E_7,E_8,F_4,G_2\), with the usual low-rank coincidences. Over an algebraically closed field, connected semisimple groups require a product of such types together with the isogeny/root-datum information; arbitrary-field forms require additional descent data.',r'The nine-family list classifies simple root-system types, not literally every semisimple algebraic group up to isomorphism.',fate=bf,refs=B,area=ba)
item(85,'P000138','construction','A real nonsplit torus',r'The real matrices \(\begin{pmatrix}a&b\\-b&a\end{pmatrix}\) are identified with nonzero complex numbers under multiplication.',r'With \(a^2+b^2\neq0\), this group is \(\operatorname{Res}_{\mathbb C/\mathbb R}\mathbb G_m\), a two-dimensional real algebraic torus. It becomes \(\mathbb G_m^2\) over \(\mathbb C\) but is not a split real torus.',r'The invertibility condition is required. The example reinforces the need to distinguish geometric tori from split tori over the given field.',fate=bf,refs=B,area=ba)
item(85,'P000138','theorem','Conjugacy of maximal tori and the rational-field caveat',r'All maximal tori are said to be conjugate.',r'Maximal tori of a connected linear algebraic group over an algebraically closed field are conjugate. For a connected reductive group over a general field, maximal split tori defined over that field are conjugate under its rational points. Arbitrary maximal real tori need not be conjugate under \(G(\mathbb R)\).',r'The nearby real example makes the distinction material. In \(SL_2(\mathbb R)\), split and compact maximal tori already show why the unqualified rational reading fails.',fate=r'The general-field split-torus theorem is a central result of \citet{borel1965reductifs}; the algebraically closed result is its standard background.',refs=B,area=ba)
save()

talk(84,'1966-02-28','M. S. Agranovich','P000133-P000136','Symbolic calculus, elliptic operators and index',r'''The continuation assembles the local calculus on a manifold and derives the Fredholm and regularity theorems from a parametrix. It then states Seeley's special degree formula for the index and ends with Hörmander's oscillatory characterization. The exact Seeley theorem, including its equivalence with vanishing of lower-rank indices, was checked in the full paper's Russian translation; the 1965 English original is the historical publication.''')
S=['seeley1965bundles'];sf=r'Already in \citet{seeley1965bundles}, \S7 and the elliptic theory, and \citet{agranovich1965elliptic}; the seminar is expository.'
item(84,'P000133','definition','Right-quantized symbol and order',r'This lecture displays the kernel using \(\sigma(y,\xi)\), and repeats the low-frequency cutoff and \(H^{\ell+s}\to H^\ell\) convention.',r'Right quantization is \(Au(x)=(2\pi)^{-n}\iint e^{i(x-y)\cdot\xi}\sigma(y,\xi)u(y)\,dy\,d\xi\). Smooth order-\(s\) symbols give the indicated Sobolev loss under proper-support or uniform global hypotheses.',r'The change from the earlier left convention affects lower terms, not the principal symbol.',fate=sf,refs=A+S)
item(84,'P000133','theorem','Product symbol and scalar commutator order',r'\(AB\) has symbol \(\sigma_1\sigma_2\) modulo a subordinate operator.',r'For smooth classical operators of orders \(s_1,s_2\), the product principal symbol is \(\sigma_{s_1}(A)\sigma_{s_2}(B)\). If the leading symbols commute, in particular for scalar operators, \([A,B]\) has order at most \(s_1+s_2-1\).',r'The lower-order commutator conclusion does not hold for arbitrary noncommuting matrix symbols.',fate=sf,refs=A+S)
item(84,'P000133','corollary' if False else 'theorem','Multiplication cutoffs and the ambiguous dash',r'The line \(\varphi A\)--\(A\varphi\) is followed by the statement that each has symbol \(\varphi\sigma\) to subordinate terms.',r'Both \(\varphi A\) and \(A\varphi\) have principal symbol \(\varphi\sigma_s(A)\); their difference has order at most \(s-1\).',r'The horizontal mark is read as separating two operators, in accordance with the Russian word meaning each. Reading it as a subtraction with principal symbol \(\varphi\sigma\) would be false.',fate=sf,refs=A+S,development='annotated')
item(84,'P000133-P000134','theorem','Separated cutoffs eliminate the principal symbol',r'For separated \(\varphi,\psi\), \(\varphi A\psi\) is subordinate, with a one-order Sobolev gain displayed.',r'If \(\varphi\psi=0\), the order-\(s\) principal symbol of \(\varphi A\psi\) vanishes. If their supports are disjoint, the smooth calculus gives an infinitely smoothing operator, a stronger assertion than the recorded one-order gain.',r'Pointwise vanishing product and disjoint closed supports are distinguished; only the latter immediately gives the full off-diagonal smoothing statement.',fate=sf,refs=A+S)
item(84,'P000133','claim','Vanishing principal symbol does not annihilate every operator',r'A smoothing order-zero operator is said to have zero symbol and therefore to vanish.',r'An operator of order zero with improved Sobolev order has zero principal order-zero symbol. In the full calculus this means that it belongs to a lower-order class; it need not be zero. Only the restricted model with a sole exactly homogeneous symbol and no independent remainder has the asserted injectivity.',r'A nonzero operator with a smooth compactly supported kernel is a direct counterexample to the unrestricted conclusion.',fate=r'The kernel of the principal-symbol map is explicitly the lower-order class in \citet{seeley1965bundles}, Theorem 7.1.',literal='false as written',refs=S,development='annotated')
item(84,'P000133-P000134','theorem','Change of coordinates and cotangent transformation',r'The symbol transforms like the highest characteristic polynomial of a differential operator.',r'Under \(y=\kappa(x)\), the transformed principal symbol is \(\widetilde\sigma(y,\eta)=\sigma(\kappa^{-1}(y),D\kappa(\kappa^{-1}(y))^T\eta)\). Bundle frames transform by the corresponding source and target changes of basis. Quantization corrections have order at most \(s-1\).',r'This covector rule is stated explicitly to avoid confusing the tangent and cotangent Jacobians.',fate=sf,refs=A+S)
item(84,'P000134','remark','Historical attributions in the calculus',r'The notes list Calderón, Zygmund, Mikhlin, Kohn, Nirenberg, Vishik, Eskin, Seeley and a name transcribed as Dynkin.',r'The manifold singular-operator reference intended in this context is A. S. Dynin, whose 1961 paper is cited in the contemporaneous literature; it is not a mathematical result of E. B. Dynkin.',r'The scan has a Dynin/Dynkin-like handwritten form. This is an identification supported by the bibliographies, not a license to silently alter the diplomatic text.',fate=r'\citet{seeley1965bundles}, bibliography item 5, identifies Dynin and the 1961 paper; \citet{kohn1965algebra} confirms the 1965 calculus chronology.',match='partial',refs=S+['kohn1965algebra'],development='annotated')
item(84,'P000134','construction','Global operators from local representatives',r'The notes impose separated-support and local-coordinate conditions, then write \(A=\sum\varphi_\nu A_\nu\psi_\nu+T\).',r'A global classical operator can be defined by compatible local operators with the cotangent transformation rule and a smooth off-diagonal kernel. A finite partition of unity on a closed manifold yields local quantizations patched by cutoffs; changing patching changes only lower-order terms at the principal-symbol level.',r'The notebook employs an order-minus-one remainder in its coarser calculus; a full classical construction refines this to asymptotic symbols modulo smoothing.',fate=r'\citet{seeley1965bundles}, Definition 7.1 and Theorem 7.1, give the precise construction.',refs=S)
item(84,'P000134','construction','Quantizing a global homogeneous symbol',r'The concluding remark says an operator can be constructed from a symbol on the cotangent bundle.',r'Every smooth degree-\(s\) homogeneous bundle homomorphism on \(T^*M\setminus0\) is the principal symbol of a classical pseudodifferential operator, obtained by local quantization and a partition of unity. The choice is unique only modulo order \(s-1\).',r'Existence does not specify a canonical quantization, and symbol equality does not mean equality of operators.',fate=r'\citet{seeley1965bundles}, Theorem 7.1.',refs=S)
item(84,'P000134','claim','The Sobolev mapping line loses an order shift',r'The handwritten line says an operator of order \(\ell\) is bounded \(H_\ell\to H_\ell\).',r'For an operator of order \(s\), the correct mapping is \(A:H^{t+s}\to H^t\), equivalently \(H^t\to H^{t-s}\), for every real Sobolev index \(t\) in the smooth closed-manifold calculus.',r'The two identical subscripts are visibly present in the scan. The preceding and subsequent lecture conventions determine the repair; it is a mathematical annotation, not an OCR correction.',fate=sf,literal='false as written',refs=A+S,development='annotated')
item(84,'P000134-P000135','method','Local proof of global composition',r'A double partition-of-unity sum for \(AB\) is rearranged by commuting cutoffs modulo subordinate terms.',r'Insert cutoffs equal to one on relevant supports; terms away from a common chart are lower order, while terms in a common chart have product principal symbols. Summing gives \(\sigma(AB)=\sigma(A)\sigma(B)\) globally.',r'The rearrangement is modulo the correct lower-order class; it is not an exact equality of the displayed localized operators.',fate=r'\citet{seeley1965bundles}, proof of Theorem 7.2, contains the corresponding localization argument.',refs=S)
item(84,'P000135','theorem','Ellipticity and the Fredholm property',r'\(\sigma(P,\xi_P)\neq0\), or nonzero determinant, is declared equivalent to being Noetherian.',r'On a closed smooth manifold, a classical operator \(A\) of order \(s\) between equal-rank complex bundles is elliptic exactly when \(A:H^{t+s}(E)\to H^t(F)\) is Fredholm, for one and then every \(t\). Ellipticity means invertibility of the principal symbol for every nonzero covector.',r'Compactness and absence of boundary are essential. On a noncompact manifold or a manifold with boundary, this statement needs additional global or boundary conditions.',fate=sf,refs=A+S)
item(84,'P000135','method','Parametrix and compact remainders',r'Quantizing \(\sigma^{-1}\) gives \(BA=I+T_1\), \(AB=I+T_2\), and finite defects.',r'An elliptic principal symbol gives an order-\(-s\) parametrix with remainders of negative order; on a closed manifold these are compact on the relevant Sobolev spaces. Consequently kernel and cokernel are finite-dimensional and the range is closed. In the full calculus the remainders can be made smoothing.',r'Compactness uses the compact Sobolev embedding. Finite-dimensional kernel alone would not establish the Fredholm property.',fate=sf,refs=A+S)
item(84,'P000135','method','Fredholm estimate forces ellipticity',r'For \(s=1\), a Fredholm estimate \(\|u\|_1\leq C(\|Au\|_0+\|u\|_0)\) and localized plane waves give the converse.',r'If a principal symbol has a null vector at \((x_0,\xi_0)\), localized high-frequency sections concentrated near \(x_0\), with phase \(\lambda x\cdot\xi_0\), contradict the Fredholm estimate after normalization. A shrinking support or a two-stage localization limit controls variation of the symbol in \(x\).',r'A single fixed bump does not literally freeze a variable symbol at \(x_0\); the localization limit is the missing step.',fate=r'\citet{seeley1965bundles}, Theorem 7.3 and the subsequent Fredholm discussion, verify the high-frequency argument.',refs=S)
item(84,'P000135','theorem','Elliptic regularity and the incorrect remainder argument',r'For \(Au=f\), order zero, \(u\in H^0\), \(f\in H^1\), the notes conclude \(u\in H^1\) using \(u+T_2f=Bf\).',r'From \(BA=I+T_1\) one obtains \(u+T_1u=Bf\). The remainder sends \(H^0\) into \(H^1\), giving the asserted gain. Iteration yields \(Au\in H^t\Rightarrow u\in H^{t+s}\) for elliptic order \(s\), locally for distributions.',r'The source term \(T_2f\) is the handwritten error; the remainder acts on \(u\), and the left parametrix determines its index.',fate=sf,literal='false as written',refs=A+S,development='annotated')
item(84,'P000135-P000136','theorem','Homotopy invariance of the index',r'The index \(\chi(A)=\dim\ker A-\dim\operatorname{coker}A\) does not change under small symbol deformations.',r'The Fredholm index is locally constant in operator norm. A continuous path of elliptic principal symbols, quantized continuously between fixed Sobolev spaces, therefore gives the same index at both ends.',r'The path must remain elliptic; an arbitrary continuous pointwise deformation without uniform control is not the asserted operator-norm statement.',fate=sf,refs=A+S)
item(84,'P000136','construction','Reducing the order without changing the index',r'\(B=A\Lambda^s\) and \(\chi(B)=\chi(A)+\chi(\Lambda^s)\), with the last index zero.',r'Choose a positive invertible elliptic order-one operator, for example \((I+\Delta)^{1/2}\) for the nonnegative Laplacian on a closed manifold. Its real powers shift Sobolev order isomorphically. Multiplying by the appropriate power reduces any order to zero without changing the index.',r'Using \(\sqrt{-\Delta}\) literally requires handling its kernel and sign convention. A self-adjoint Fredholm operator has index zero but need not be invertible.',fate=sf,refs=A+S)
item(84,'P000136','theorem','Seeley degree formula and the lower-rank obstruction',r'The notes give \(\operatorname{ind}A=\deg(\rho\sigma)/(n-1)!\) if and only if every \((n-1)\)-square system has zero index; boundaries in \(\mathbb R^{n+1}\) are mentioned.',r'For elliptic \(n\times n\) systems on a closed \(n\)-manifold with unitary principal symbol \(\sigma:S^*M\to U(n)\), suitable fixed orientations make \((n-1)!\operatorname{ind}A=\deg(\rho\circ\sigma)\) for every such system if and only if every elliptic \((n-1)\times(n-1)\) system on \(M\) has index zero. Here \(\rho:U(n)\to S^{2n-1}\) selects a column.',r'This is a theorem about systems on trivial bundles with a global matrix symbol. The quantified equivalence, orientation choice and manifold restriction prevent treating it as a universal degree formula for all bundles.',fate=r'Exact match: \citet{seeley1965bundles}, Appendix A.3, Theorem 2 (Russian translation p. 95), including the boundary example.',refs=S)
item(84,'P000136','theorem','External product of elliptic operators',r'The operation \(A\#B\) satisfies \(\operatorname{ind}(A\#B)=\operatorname{ind}A\operatorname{ind}B\).',r'The elliptic external product, formed with the standard graded tensor-product symbol and realized on the product manifold, has index equal to the product of the two indices. It is distinct from ordinary composition, whose index is additive.',r'The notebook does not define \(\#\); its identification is fixed by the Seeley reference and the displayed multiplicativity.',fate=r'\citet{seeley1965bundles}, Theorem 13.2 and Appendix A.2, give the operation used here.',refs=S)
item(84,'P000136','method','Hörmander oscillatory characterization',r'\(e^{-i\lambda g}A(fe^{i\lambda g})\sim\sum_jP_j(f,g)\lambda^{s_j}\), \(s_j\downarrow-\infty\), with \(dg\neq0\) on \(\operatorname{supp}f\), bounded remainders and continuous \(A:C_c^\infty\to C^\infty\).',r'A classical smooth operator can be characterized through its complete high-frequency action on localized nonstationary phases. In the usual classical order-\(s\) case the exponents are \(s-j\); each normalized remainder is bounded in every prescribed \(C^q\) seminorm, uniformly for compact families of admissible phases. Linear phases recover the symbol.',r'The notebook allows a more general decreasing sequence of exponents and leaves the precise converse class implicit. This entry records the characterization method, not an unverified full equivalence for every such sequence.',fate=r'\citet{hormander1965pseudo} predates the talk. Publisher metadata and the 1965 publication were checked; the exact generalized-exponent formulation has not been verified against its full theorem.',match='partial',verification='publisher metadata checked',refs=['hormander1965pseudo'],confidence='medium')
save()

talk(82,'1966-02-21','I. M. Gelfand','P000128-P000132','Integral geometry on affine k-planes',r'''The lecture develops differential forms attached to the affine \(k\)-plane transform: a generalized determinant, a closedness criterion for the range, and inversion by integrating over cycles. The close publication is \citet{gelfand1967planes}, with Graev and Shapiro. Its hypotheses and quantifiers correct two potentially serious overstatements in the notebook. P000128 starts this record after Agranovich; P000132 ends it before Karpelevich.''')
G=['gelfand1967planes']
gf=r'Published soon after in \citet{gelfand1967planes}; the relevant definitions and Theorems 1--2 were checked in the Russian full text.'
ga='Integral geometry'
item(82,'P000128','problem','Reconstruction from k-plane integrals and economical families',r'Reconstruct \(f\) from \(\varphi(h)=\int_hf\); for lines in \(\mathbb R^3\), can the four-parameter data be reduced to three parameters?',r'For a rapidly decreasing smooth function on affine space, recover \(f\) from its integrals over affine \(k\)-planes. For a prescribed smaller family, an inversion question additionally requires its geometry and a nonvanishing inversion coefficient; mere equality of parameter counts does not imply injectivity.',r'The first question is precise. The three-parameter subfamily is not specified; later cycle formulas answer an appropriate family-dependent version, not every subfamily.',cls='A',fate=gf,present='As of November 2026: the full-data problem and admissible cycle inversions are established; the unspecified economical-family sentence does not define a further open problem.',match='partial',problem='GP-1965-L01',refs=G,area=ga)
item(82,'P000129','construction','Affine-plane bundle and translation-incidence section',r'\(H_{n,k}\) consists of affine \(k\)-planes with volume data, \(G\) records parallel classes, and \(S_\beta\) selects the translate through \(\beta\).',r'An affine plane is \(\alpha+b\), where \(\alpha\in\operatorname{Gr}(k,\mathbb F^n)\) and \(b\in\mathbb F^n/\alpha\), with compatible real or complex volume normalization. The pullback \(\varphi(\alpha,\beta)\) depends only on \(\beta\bmod\alpha\).',r'Volume weights must transform with a change of frame. The real and complex versions use different integration densities; they cannot be interchanged without a normalization convention.',cls='A',fate=gf,refs=G,area=ga)
item(82,'P000129-P000130','construction','Determinant of vector entries paired with a symmetric form',r'For a symmetric \(k\)-linear form \(B\), the notes define a signed sum over permutations of entries \(\xi_{ij}\).',r'For vectors \(\xi_{ij}\in W\), set \(\det_B(\xi)=\sum_{\pi\in S_k}\operatorname{sgn}(\pi)B(\xi_{1\pi(1)},\ldots,\xi_{k\pi(k)})\). Symmetry of \(B\) makes this alternating in rows and columns. If \(B\) vanishes whenever an argument belongs to \(\alpha\), the expression descends to \(W/\alpha\).',r'This is a polarized determinant, not a determinant with an unspecified multiplication on \(W\).',cls='A',fate=gf,literal='correct',refs=G,area=ga)
item(82,'P000130','construction','Translation derivatives define a differential form on directions',r'The symmetric derivative \(\partial_\beta^k\varphi\) and nearby frames \(e_i+\xi_{ij}\) produce a \(k\)-form; frame-independence is Theorem 1.',r'The identification \(T_\alpha\operatorname{Gr}(k,\mathbb F^n)=\operatorname{Hom}(\alpha,\mathbb F^n/\alpha)\) lets the polarized determinant pair the translation derivative with \(k\) tangent directions. The accompanying frame-volume factor makes the result intrinsic. In the complex formulation the corresponding object has bidegree \((k,k)\), with holomorphic and antiholomorphic derivative factors.',r'The real \(k\)-form and complex \((k,k)\)-form are distinguished explicitly. Indexing a basis of \(\alpha\) uses \(k\) entries, even where the notebook writes \(n\).',cls='A',fate=gf,refs=G,area=ga)
item(82,'P000130-P000131','theorem','Closedness characterizes the range with restricted k and decay',r'Theorem 2 says \(\varphi\) is in the plane-transform range if and only if its associated form is closed.',r'In the smooth rapidly decreasing class \(\Phi\) of the published theorem, with rapid decay in the translation variable together with all derivatives, and \(1\leq k<n-1\), the Gelfand--Graev--Shapiro closedness equations characterize the transform range. The paper gives the complex theorem and notes its real analogue. The case \(k=n-1\) is excluded.',r'These hypotheses are restored from the published Theorem 1, not inferred from the short notebook theorem. For hyperplanes, closedness in top degree cannot substitute for the missing global moment conditions.',cls='A',fate=r'\citet{gelfand1967planes}, Theorem 1, p. 23 of the Russian edition, and its two footnotes explicitly impose the restriction and discuss the real version.',present='As of November 2026: established for the published range class; the unrestricted notebook wording is not a valid universal characterization.',literal='correct with missing hypotheses',problem='GP-1965-L01',refs=G,area=ga,development='annotated')
item(82,'P000131','theorem','Cycle inversion and its homological coefficient',r'Theorem 3 states \(\int_\gamma\kappa\varphi=C_\gamma f(\beta)\); \(C_\gamma\) is topological.',r'For transform data \(\varphi=R_k f\) and an admissible closed cycle in the direction Grassmannian, integration of the associated form through \(\beta\) equals a fixed homological pairing times \(f(\beta)\). The cycle has real dimension \(k\) in the real construction and \(2k\) in the complex construction. It yields inversion only if its pairing is nonzero.',r'Orientations, density normalization and the relevant homology class determine \(C_\gamma\). A merely parameter-counting choice of cycle is insufficient.',cls='A',fate=r'\citet{gelfand1967planes}, Theorem 2 and the subsequent cycle calculation, pp. 29--31, establish this formula.',problem='GP-1965-L01',refs=G,area=ga)
item(82,'P000131','claim','Nonzero complex coefficient is an existence statement',r'The notes suggest that in the complex case the coefficient is always nonzero, with a contrast to real parity.',r'For complex affine \(k\)-planes there exist \(2k\)-cycles with nonzero inversion coefficient. An arbitrary cycle can have zero coefficient, including a null-homologous cycle or the zero class. The real local differential inversion has the familiar parity obstruction for odd \(k\).',r'The published theorem has an existential quantifier. This is a substantive correction to the literal universal wording, not a new open case.',cls='A',fate=r'\citet{gelfand1967planes}, Theorem 2, states existence of a suitable nonzero class; it does not assert nonvanishing on every cycle.',literal='false as written',refs=G,area=ga,development='annotated')
item(82,'P000131','construction','Delta-current form of the inversion identity',r'The notes give the distributional identity \(C_\gamma\delta_\beta=\int_\gamma\kappa\delta_h\).',r'Interpret plane integration as pairing with the plane delta distribution. Applying the derivative-form construction and then integrating over the admissible cycle gives the evaluation current \(C_\gamma\delta_\beta\), with the same conventions as the function inversion theorem.',r'The formula is an equality of distributions, after pairing with test functions; it is not a pointwise product of delta functions.',cls='A',fate=gf,refs=G,area=ga)
item(82,'P000131-P000132','construction','Complex-line coordinates and the (1,1)-form',r'Lines are written \(x=\alpha t+\beta\), with integration \(dt\,d\bar t\); a form involving \(\partial_{\beta_i}d\alpha_i\) and its conjugate is displayed.',r'On the graph chart \(x_j=\alpha_jx_n+\beta_j\), \(j=1,\ldots,n-1\), the line space has complex dimension \(2(n-1)\). Up to the volume factor, the form is \(\kappa\varphi=\sum_{i,j}\partial_{\beta_i}\partial_{\bar\beta_j}\varphi\,d\alpha_i\wedge d\bar\alpha_j\).',r'Writing arbitrary \(n\)-vectors \(\alpha,\beta\) introduces the reparametrizations \((\alpha,\beta)\sim(\lambda\alpha,\beta+t_0\alpha)\). The graph chart removes this redundancy and fixes the derivative order.',cls='A',fate=gf,refs=G,area=ga)
item(82,'P000132','remark','Incomplete delta-kernel calculation at the lecture boundary',r'The last formula represents line constraints by delta factors; part of the final expression is cancelled or unfinished before Karpelevich begins.',r'The readable graph constraints define a plane delta kernel. No further definite equality can be reconstructed from the cancelled ending without specifying its coefficient, densities and differentiation conventions.',r'Only the valid kernel construction is retained. The erased remainder is not promoted to a theorem.',cls='F',fate=r'\citet{gelfand1967planes} and \citet{gelfand1969forms} provide the surrounding method, but not a recoverable identity for the cancelled line.',present='As of November 2026: the incomplete expression remains textually indeterminate; the surrounding inversion method is established.',literal='not determinable',match='thematic only',verification='unresolved lead',refs=G+['gelfand1969forms'],confidence='low',area=ga)
problems.append(dict(id='GP-1965-L01',title='Range and cycle inversion for the affine k-plane transform',statement=r'Characterize the rapidly decreasing affine \(k\)-plane transform data by differential conditions, and recover the original function by integration over a suitable cycle of directions; specify which cycle classes give a nonzero coefficient.',occurrences=['1965-82.1','1965-82.5','1965-82.6'],status=r'As of November 2026: the precise range theorem for \(1\leq k<n-1\) and the complex cycle inversion theorem are established in \citet{gelfand1967planes}. The notebook does not specify an additional open family-selection problem.',status_date='2026-11',refs=G))
save()

talk(83,'1966-02-21','F. I. Karpelevich','P000132-P000133','Klein on the spinning top',r'''A short exposition of Klein's Princeton lectures describes rotations by fractional linear transformations and reduces a top problem to an elliptic integral. The lecture crosses the page boundary: its final quadrature is at the top of P000133, before the dated Agranovich continuation. The two cyclic-momentum formulas contain a factor-of-two slip already present in the handwriting.''')
K=['klein1897top'];kf=r'The subject is explicitly Klein; \citet{klein1897top}, the published Princeton lectures, predates this exposition by nearly seventy years.'
ka='Classical mechanics and elliptic functions'
item(83,'P000132','construction','Euler angles and a curve in SO(3)',r'A motion of the top is a curve in \(SO(3)\), factored as successive rotations with angles \(\varphi,\theta,\psi\).',r'A fixed-point rigid-body attitude is \(R(t)\in SO(3)\). Away from the polar coordinate singularities it admits Euler-angle coordinates, with the middle angle \(\theta\) measuring the inclination of the body axis.',r'The factor ordering and sign convention fix the names of the conserved momenta; the subsequent equations are read consistently with the displayed kinetic energy.',fate=kf,literal='correct',refs=K,area=ka)
item(83,'P000132','construction','Rotations as fractional linear transformations',r'The notes identify rotations with fractional linear transformations and draw the unitary two-by-two matrix.',r'The action of \(SU(2)\) on the Riemann sphere by \(z\mapsto(az+b)/(-\bar bz+\bar a)\), \(|a|^2+|b|^2=1\), has kernel \(\{\pm I\}\) and gives \(SO(3)\cong PSU(2)\).',r'The isomorphism is with the projective transformations, not with the matrix group \(SU(2)\) itself.',fate=kf,refs=K,area=ka)
item(83,'P000132','construction','Normalized spherical-top Lagrangian',r'\(T=\tfrac12(\dot\varphi^2+\dot\psi^2+2\dot\varphi\dot\psi\cos\theta+\dot\theta^2)\), \(V=p\cos\theta\).',r'For equal normalized principal moments of inertia and potential \(V=p\cos\theta\), set \(L=T-V\). The coordinates \(\varphi,\psi\) are cyclic and energy \(h=T+p\cos\theta\) is conserved.',r'The printed kinetic energy is the spherical-inertia specialization; the general symmetric top has two moments of inertia and a different coefficient pattern.',fate=kf,refs=K,area=ka)
item(83,'P000132','claim','Correct cyclic momenta',r'The handwritten first integrals contain \(\dot\varphi+2\dot\psi\cos\theta=n\) and \(\dot\psi+2\dot\varphi\cos\theta=e\).',r'Differentiation of the recorded \(L\) gives \(n=\dot\varphi+\dot\psi\cos\theta\), \(e=\dot\psi+\dot\varphi\cos\theta\). Thus for \(u=\cos\theta\), \(\dot\varphi=(n-eu)/(1-u^2)\), \(\dot\psi=(e-nu)/(1-u^2)\), when \(|u|<1\).',r'The two factors 2 are inconsistent with the preceding one-half in \(T\). The corrections follow independently from differentiating that displayed kinetic energy, not from changing the physical model.',fate=kf,literal='false as written',refs=K,area=ka,development='annotated')
item(83,'P000132-P000133','method','The cubic governing nutation',r'Elimination leads to \(dt=du/\sqrt{U(u)}\), where \(U\) is indicated as cubic but not completely expanded.',r'With the corrected momenta, \(\dot u^2=U(u)=2(h-pu)(1-u^2)-n^2-e^2+2neu\). Equivalently, \(U(u)=2pu^3-2hu^2+2(ne-p)u+2h-n^2-e^2\). Physical intervals also require \(|u|\leq1\) and \(U(u)\geq0\).',r'This full polynomial is an independent reconstruction; it is not a completed transcription of the truncated notebook expression.',fate=kf,refs=K,area=ka,development='annotated')
item(83,'P000133','theorem','Elliptic quadrature and degenerate limits',r'The top of P000133 identifies the integral as elliptic.',r'For a cubic \(U\) with distinct roots, the curve \(v^2=U(u)\) has genus one, and \(t-t_0=\pm\int_{u_0}^u ds/\sqrt{U(s)}\) gives the nutation locally; its inversion is elliptic. Multiple-root and degree-drop cases degenerate and require separate elementary limiting formulas.',r'The sign chooses a motion branch. The assertion does not exclude stationary solutions or repeated-root trajectories.',fate=kf,refs=K,area=ka)
save()

